173	+void AgentHost::handle_skills(const std::string& envelope_id, const std::string& payload_json)
174	+{
175	+    // Every skill in one message, sorted by name. A skill has a trigger, a
176	+    // description or both, and at most one has each trigger: the host fires
177	+    // a skill by the event its trigger names, and the model reads a
178	+    // described one by name. A payload that breaks a rule is refused whole
179	+    // and the skills received before stay in force.
180	+    constexpr std::size_t kSkillTextLimit        = 16 * 1024;
181	+    constexpr std::size_t kSkillDescriptionLimit = 300;
182	+    constexpr std::size_t kSkillsPayloadLimit    = 256 * 1024;
183	+    const json parsed = payload_json.size() <= kSkillsPayloadLimit ? json::parse(payload_json, nullptr, false) : json();
184	+    bool valid = parsed.is_object() && parsed.size() == 1 && parsed.contains("skills") && parsed["skills"].is_array();
185	+    std::vector<AgentSkill> received;
186	+    std::set<std::string>   triggers;
187	+    if (valid)
188	+        for (const json& value : parsed["skills"]) {
189	+            valid = value.is_object();
190	+            if (valid)
191	+                for (const auto& [key, field] : value.items())
192	+                    valid = valid && field.is_string() &&
193	+                            (key == "name" || key == "trigger" || key == "description" || key == "text");
194	+            if (!valid)
195	+                break;
196	+            AgentSkill skill{value.value("name", ""), value.value("trigger", ""), value.value("description", ""),
197	+                             value.value("text", "")};
198	+            const bool trigger_ok     = !value.contains("trigger") ||
199	+                                        (valid_skill_word_list(skill.trigger, '_') && triggers.insert(skill.trigger).second);
200	+            const bool description_ok = !value.contains("description") ||
201	+                                        (!skill.description.empty() && skill.description.size() <= kSkillDescriptionLimit &&
202	+                                         skill.description.find_first_of("\r\n") == std::string::npos);
203	+            if (!valid_skill_word_list(skill.name, '-') || skill.text.empty() || skill.text.size() > kSkillTextLimit ||
204	+                (skill.trigger.empty() && skill.description.empty()) || !trigger_ok || !description_ok ||
205	+                (!received.empty() && skill.name <= received.back().name)) {
206	+                valid = false;
207	+                break;
208	+            }
209	+            received.push_back(std::move(skill));
210	+        }
211	+    if (!valid) {
212	+        send_bridge_error("invalid_payload", "The project skills are invalid.", envelope_id);
213	+        return;
214	+    }
215	+    m_skills          = std::move(received);
216	+    m_skills_received = true;
217	+    // A turn the app started before the page had sent them waited in the
218	+    // queue; see begin_reply.
219	+    start_next_queued_reply();
220	+}
