    };
    for (const Source& source : sources) {
        DYNAMIC_SECTION(source.tool)
        {
            auto agent_owner = std::make_unique<OneCallAgent>();
            OneCallAgent* agent = agent_owner.get();
            agent->call = [&source](const AgentRequest& request) {
